<script setup>
import { computed, onMounted, ref } from 'vue'
import { getApiError } from '../../api/client'
import { students, guardians } from '../../api/students'
import { academicYears, classes, streams } from '../../api/schoolStructure'

const rows=ref([]), selected=ref(null), loading=ref(true), saving=ref(false), error=ref(''), notice=ref(''), search=ref(''), status=ref('')
const years=ref([]), classRows=ref([]), streamRows=ref([]), guardianRows=ref([])
const showCreate=ref(false), showEditStudent=ref(false), showGuardian=ref(false), showCreateGuardian=ref(false), showEditGuardian=ref(false), showEnrollment=ref(false), showEditEnrollment=ref(false)
const blankStudent=()=>({admission_number:'',first_name:'',middle_name:'',last_name:'',date_of_birth:'',gender:'unspecified',nationality:'Kenyan',birth_certificate_number:'',admission_date:'',previous_school:'',status:'active',medical_notes:'',emergency_notes:''})
const form=ref(blankStudent()), editForm=ref(blankStudent())
const guardianForm=ref({guardian_id:'',relationship:'Parent',is_primary:true,is_emergency_contact:true,can_pick_up:true})
const newGuardianForm=ref({first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'})
const guardianEditForm=ref({...newGuardianForm.value})
const enrollmentForm=ref({academic_year_id:'',class_level_id:'',stream_id:'',enrollment_date:new Date().toISOString().slice(0,10),exit_date:'',status:'active',notes:''})
const enrollmentEditForm=ref({...enrollmentForm.value})
const fullName=s=>[s?.first_name,s?.middle_name,s?.last_name].filter(Boolean).join(' ')
const flash=m=>{notice.value=m;setTimeout(()=>notice.value='',3000)}
const availableStreams=computed(()=>streamRows.value.filter(s=>!enrollmentForm.value.class_level_id||s.class_level_id===enrollmentForm.value.class_level_id))
const editAvailableStreams=computed(()=>streamRows.value.filter(s=>!enrollmentEditForm.value.class_level_id||s.class_level_id===enrollmentEditForm.value.class_level_id))

async function load(){loading.value=true;error.value='';try{rows.value=await students.list({search:search.value||undefined,status:status.value||undefined})}catch(e){error.value=getApiError(e)}finally{loading.value=false}}
async function options(){try{[years.value,classRows.value,streamRows.value,guardianRows.value]=await Promise.all([academicYears.list(),classes.list(),streams.list(),guardians.list()])}catch(e){error.value=getApiError(e)}}
function newStudent(){form.value=blankStudent();showCreate.value=true}
async function createStudent(){saving.value=true;try{await students.create(form.value);showCreate.value=false;await load();flash('Student admitted successfully.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
function editStudent(){editForm.value={...blankStudent(),...selected.value};showEditStudent.value=true}
async function saveStudentEdit(){saving.value=true;try{await students.update(selected.value.id,editForm.value);selected.value=await students.get(selected.value.id);showEditStudent.value=false;await load();flash('Student profile updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function openStudent(s){try{selected.value=await students.get(s.id)}catch(e){error.value=getApiError(e)}}
function linkForm(){guardianForm.value={guardian_id:'',relationship:'Parent',is_primary:true,is_emergency_contact:true,can_pick_up:true};showGuardian.value=true}
function createGuardianForm(){newGuardianForm.value={first_name:'',last_name:'',phone:'',alternative_phone:'',email:'',address:'',occupation:'',employer:'',preferred_contact_method:'phone',status:'active'};showCreateGuardian.value=true}
async function createGuardian(){saving.value=true;try{const g=await guardians.create(newGuardianForm.value);await options();guardianForm.value={guardian_id:g.id,relationship:'Parent',is_primary:!selected.value.guardians?.length,is_emergency_contact:true,can_pick_up:true};showCreateGuardian.value=false;showGuardian.value=true;flash('Guardian created. Complete the relationship to link them.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function linkGuardian(){saving.value=true;try{await students.linkGuardian(selected.value.id,guardianForm.value);selected.value=await students.get(selected.value.id);showGuardian.value=false;await options();flash('Guardian linked.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
function editGuardian(g){guardianEditForm.value={...g.guardian};guardianEditForm.value._id=g.guardian_id;showEditGuardian.value=true}
async function saveGuardianEdit(){saving.value=true;try{const id=guardianEditForm.value._id;const payload={...guardianEditForm.value};delete payload._id;await guardians.update(id,payload);selected.value=await students.get(selected.value.id);await options();showEditGuardian.value=false;flash('Guardian updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function unlinkGuardian(g){if(!confirm(`Remove ${fullName(g.guardian)} from this student?`))return;try{await students.unlinkGuardian(selected.value.id,g.guardian_id);selected.value=await students.get(selected.value.id);flash('Guardian removed.')}catch(e){error.value=getApiError(e)}}
function enrollmentFormOpen(){enrollmentForm.value={academic_year_id:years.value.find(y=>y.is_current)?.id||years.value[0]?.id||'',class_level_id:'',stream_id:'',enrollment_date:new Date().toISOString().slice(0,10),exit_date:'',status:'active',notes:''};showEnrollment.value=true}
function editEnrollment(e){enrollmentEditForm.value={academic_year_id:e.academic_year_id,class_level_id:e.class_level_id,stream_id:e.stream_id||'',enrollment_date:e.enrollment_date,exit_date:e.exit_date||'',status:e.status,notes:e.notes||'',_id:e.id};showEditEnrollment.value=true}
async function enroll(){saving.value=true;try{await students.enroll(selected.value.id,{...enrollmentForm.value,stream_id:enrollmentForm.value.stream_id||null,exit_date:enrollmentForm.value.exit_date||null});selected.value=await students.get(selected.value.id);showEnrollment.value=false;flash('Enrollment saved.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
async function saveEnrollmentEdit(){saving.value=true;try{const id=enrollmentEditForm.value._id;const payload={...enrollmentEditForm.value};delete payload._id;payload.stream_id=payload.stream_id||null;payload.exit_date=payload.exit_date||null;await students.updateEnrollment(selected.value.id,id,payload);selected.value=await students.get(selected.value.id);showEditEnrollment.value=false;flash('Enrollment updated.')}catch(e){error.value=getApiError(e)}finally{saving.value=false}}
onMounted(()=>Promise.all([load(),options()]))
</script>
<template><div class="students-page"><div class="page-title-row"><div><div class="eyebrow">STUDENT MANAGEMENT</div><h1>Students</h1><p>Admissions, student profiles, guardians and enrollment history.</p></div><button class="btn btn-primary" @click="newStudent"><i class="bi bi-person-plus me-2"></i>Add student</button></div><div v-if="notice" class="alert alert-success border-0 shadow-sm">{{notice}}</div><div v-if="error" class="alert alert-danger border-0 shadow-sm">{{error}}</div><section class="dashboard-card mb-4"><div class="student-toolbar"><div class="search-box"><i class="bi bi-search"></i><input v-model="search" @keyup.enter="load" placeholder="Search admission number or name..." /></div><select v-model="status" class="form-select" @change="load"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="graduated">Graduated</option><option value="transferred">Transferred</option><option value="withdrawn">Withdrawn</option></select><button class="btn btn-light" @click="load"><i class="bi bi-arrow-clockwise"></i></button></div></section><div class="row g-4"><div :class="selected?'col-xl-7':'col-12'"><section class="dashboard-card"><div class="card-heading"><div><h2>Student register</h2><p>{{rows.length}} student{{rows.length===1?'':'s'}} shown</p></div></div><div v-if="loading" class="py-5 text-center"><span class="spinner-border text-primary"></span></div><div v-else-if="!rows.length" class="empty-state"><i class="bi bi-people"></i><h3>No students yet</h3><p>Start by admitting your first student.</p><button class="btn btn-primary" @click="newStudent">Add first student</button></div><div v-else class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Admission</th><th>Student</th><th>Class</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td class="fw-semibold">{{s.admission_number}}</td><td><button class="student-link" @click="openStudent(s)">{{fullName(s)}}</button></td><td>{{s.current_class_name||'Not enrolled'}}</td><td><span class="status-pill" :class="s.status">{{s.status}}</span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary me-1" @click="openStudent(s)"><i class="bi bi-pencil-square"></i></button><button class="btn btn-sm btn-light" @click="openStudent(s)"><i class="bi bi-chevron-right"></i></button></td></tr></tbody></table></div></section></div><div v-if="selected" class="col-xl-5"><section class="dashboard-card student-detail-card"><div class="detail-head"><div class="student-avatar">{{selected.first_name?.[0]}}{{selected.last_name?.[0]}}</div><div><div class="eyebrow">{{selected.admission_number}}</div><h2>{{fullName(selected)}}</h2><span class="status-pill" :class="selected.status">{{selected.status}}</span></div><button class="btn btn-sm btn-light ms-auto" @click="selected=null"><i class="bi bi-x-lg"></i></button></div><div class="detail-actions"><button class="btn btn-outline-primary btn-sm" @click="editStudent"><i class="bi bi-pencil me-1"></i>Edit profile</button><button class="btn btn-primary btn-sm" @click="enrollmentFormOpen"><i class="bi bi-mortarboard me-1"></i>Enroll</button><button class="btn btn-outline-primary btn-sm" @click="linkForm"><i class="bi bi-person-plus me-1"></i>Guardian</button><button class="btn btn-outline-secondary btn-sm" @click="createGuardianForm"><i class="bi bi-person-plus-fill me-1"></i>New guardian</button></div><div class="detail-section"><h3>Profile</h3><div class="detail-grid"><div><small>Date of birth</small><strong>{{selected.date_of_birth||'Not provided'}}</strong></div><div><small>Gender</small><strong class="text-capitalize">{{selected.gender}}</strong></div><div><small>Admission date</small><strong>{{selected.admission_date||'Not provided'}}</strong></div><div><small>Nationality</small><strong>{{selected.nationality||'Not provided'}}</strong></div></div></div><div class="detail-section"><div class="section-title"><h3>Guardians</h3><button class="btn btn-link btn-sm" @click="linkForm">Add</button></div><div v-if="!selected.guardians?.length" class="mini-empty">No guardians linked.</div><div v-for="g in selected.guardians" :key="g.id" class="related-row"><div class="mini-avatar">{{g.guardian?.first_name?.[0]}}{{g.guardian?.last_name?.[0]}}</div><div><strong>{{fullName(g.guardian)}}</strong><small>{{g.relationship}}<span v-if="g.is_primary"> · Primary</span></small></div><button class="btn btn-sm btn-light ms-1" @click="editGuardian(g)"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-light ms-auto" @click="unlinkGuardian(g)"><i class="bi bi-x"></i></button></div></div><div class="detail-section"><div class="section-title"><h3>Enrollment history</h3><button class="btn btn-link btn-sm" @click="enrollmentFormOpen">Add</button></div><div v-if="!selected.enrollments?.length" class="mini-empty">No enrollment history.</div><div v-for="e in selected.enrollments" :key="e.id" class="history-row"><div><strong>{{e.academic_year_name}}</strong><small>{{e.class_name}}<span v-if="e.stream_name"> · {{e.stream_name}}</span></small></div><span class="status-pill" :class="e.status">{{e.status}}</span><button class="btn btn-sm btn-light ms-2" @click="editEnrollment(e)"><i class="bi bi-pencil"></i></button></div></div></section></div></div>
<div v-if="showCreate||showEditStudent" class="modal-backdrop-custom"><div class="modal-card modal-wide"><div class="modal-head"><div><h2>{{showEditStudent?'Edit student':'Admit student'}}</h2><p>{{showEditStudent?'Update the student master profile.':'Create the student\'s master profile.'}}</p></div><button class="btn btn-light" @click="showCreate=false;showEditStudent=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-md-4"><label>Admission number *</label><input :value="showEditStudent?editForm.admission_number:form.admission_number" class="form-control" disabled></div><div class="col-md-4"><label>First name *</label><input v-model="(showEditStudent?editForm:form).first_name" class="form-control"></div><div class="col-md-4"><label>Last name *</label><input v-model="(showEditStudent?editForm:form).last_name" class="form-control"></div><div class="col-md-6"><label>Middle name</label><input v-model="(showEditStudent?editForm:form).middle_name" class="form-control"></div><div class="col-md-3"><label>Date of birth</label><input v-model="(showEditStudent?editForm:form).date_of_birth" type="date" class="form-control"></div><div class="col-md-3"><label>Gender</label><select v-model="(showEditStudent?editForm:form).gender" class="form-select"><option value="unspecified">Unspecified</option><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></div><div class="col-md-4"><label>Nationality</label><input v-model="(showEditStudent?editForm:form).nationality" class="form-control"></div><div class="col-md-4"><label>Birth certificate no.</label><input v-model="(showEditStudent?editForm:form).birth_certificate_number" class="form-control"></div><div class="col-md-4"><label>Admission date</label><input v-model="(showEditStudent?editForm:form).admission_date" type="date" class="form-control"></div><div v-if="showEditStudent" class="col-md-4"><label>Status</label><select v-model="editForm.status" class="form-select"><option value="active">Active</option><option value="inactive">Inactive</option><option value="graduated">Graduated</option><option value="transferred">Transferred</option><option value="withdrawn">Withdrawn</option></select></div><div class="col-md-8"><label>Previous school</label><input v-model="(showEditStudent?editForm:form).previous_school" class="form-control"></div><div class="col-12"><label>Medical notes</label><textarea v-model="(showEditStudent?editForm:form).medical_notes" class="form-control" rows="2"></textarea></div><div class="col-12"><label>Emergency notes</label><textarea v-model="(showEditStudent?editForm:form).emergency_notes" class="form-control" rows="2"></textarea></div></div><div class="modal-actions"><button class="btn btn-light" @click="showCreate=false;showEditStudent=false">Cancel</button><button v-if="showEditStudent" class="btn btn-primary" :disabled="saving||!editForm.first_name||!editForm.last_name" @click="saveStudentEdit">{{saving?'Updating...':'Update student'}}</button><button v-else class="btn btn-primary" :disabled="saving||!form.admission_number||!form.first_name||!form.last_name" @click="createStudent">{{saving?'Saving...':'Admit student'}}</button></div></div></div>
<div v-if="showCreateGuardian" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>New guardian</h2><p>Create a guardian profile before linking them to a student.</p></div><button class="btn btn-light" @click="showCreateGuardian=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-6"><label>First name *</label><input v-model="newGuardianForm.first_name" class="form-control"></div><div class="col-6"><label>Last name *</label><input v-model="newGuardianForm.last_name" class="form-control"></div><div class="col-6"><label>Phone</label><input v-model="newGuardianForm.phone" class="form-control"></div><div class="col-6"><label>Alternative phone</label><input v-model="newGuardianForm.alternative_phone" class="form-control"></div><div class="col-12"><label>Email</label><input v-model="newGuardianForm.email" type="email" class="form-control"></div><div class="col-12"><label>Address</label><input v-model="newGuardianForm.address" class="form-control"></div><div class="col-6"><label>Occupation</label><input v-model="newGuardianForm.occupation" class="form-control"></div><div class="col-6"><label>Employer</label><input v-model="newGuardianForm.employer" class="form-control"></div><div class="col-12"><label>Preferred contact</label><select v-model="newGuardianForm.preferred_contact_method" class="form-select"><option value="phone">Phone</option><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="any">Any</option></select></div></div><div class="modal-actions"><button class="btn btn-light" @click="showCreateGuardian=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!newGuardianForm.first_name||!newGuardianForm.last_name" @click="createGuardian">{{saving?'Saving...':'Create guardian'}}</button></div></div></div>
<div v-if="showEditGuardian" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Edit guardian</h2><p>Update guardian contact details.</p></div><button class="btn btn-light" @click="showEditGuardian=false"><i class="bi bi-x-lg"></i></button></div><div class="row g-3"><div class="col-6"><label>First name *</label><input v-model="guardianEditForm.first_name" class="form-control"></div><div class="col-6"><label>Last name *</label><input v-model="guardianEditForm.last_name" class="form-control"></div><div class="col-6"><label>Phone</label><input v-model="guardianEditForm.phone" class="form-control"></div><div class="col-6"><label>Alternative phone</label><input v-model="guardianEditForm.alternative_phone" class="form-control"></div><div class="col-12"><label>Email</label><input v-model="guardianEditForm.email" type="email" class="form-control"></div><div class="col-12"><label>Address</label><input v-model="guardianEditForm.address" class="form-control"></div><div class="col-6"><label>Occupation</label><input v-model="guardianEditForm.occupation" class="form-control"></div><div class="col-6"><label>Employer</label><input v-model="guardianEditForm.employer" class="form-control"></div><div class="col-12"><label>Preferred contact</label><select v-model="guardianEditForm.preferred_contact_method" class="form-select"><option value="phone">Phone</option><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="any">Any</option></select></div><div class="col-12"><label>Status</label><select v-model="guardianEditForm.status" class="form-select"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><div class="modal-actions"><button class="btn btn-light" @click="showEditGuardian=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!guardianEditForm.first_name||!guardianEditForm.last_name" @click="saveGuardianEdit">{{saving?'Updating...':'Update guardian'}}</button></div></div></div>
<div v-if="showGuardian" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>Link guardian</h2><p>Connect a guardian to {{fullName(selected)}}.</p></div><button class="btn btn-light" @click="showGuardian=false"><i class="bi bi-x-lg"></i></button></div><label>Guardian *</label><select v-model="guardianForm.guardian_id" class="form-select mb-3"><option value="">Select guardian</option><option v-for="g in guardianRows" :key="g.id" :value="g.id">{{fullName(g)}}{{g.phone?' · '+g.phone:''}}</option></select><label>Relationship *</label><input v-model="guardianForm.relationship" class="form-control mb-3"><div class="form-check mb-2"><input v-model="guardianForm.is_primary" class="form-check-input" type="checkbox" id="primary"><label for="primary">Primary guardian</label></div><div class="form-check mb-2"><input v-model="guardianForm.is_emergency_contact" class="form-check-input" type="checkbox" id="emergency"><label for="emergency">Emergency contact</label></div><div class="form-check mb-4"><input v-model="guardianForm.can_pick_up" class="form-check-input" type="checkbox" id="pickup"><label for="pickup">Can pick up student</label></div><div class="modal-actions"><button class="btn btn-light" @click="showGuardian=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!guardianForm.guardian_id" @click="linkGuardian">Link guardian</button></div></div></div>
<div v-if="showEnrollment||showEditEnrollment" class="modal-backdrop-custom"><div class="modal-card"><div class="modal-head"><div><h2>{{showEditEnrollment?'Edit enrollment':'Enroll student'}}</h2><p>{{showEditEnrollment?'Update the academic-year placement.':'Add an academic-year placement.'}}</p></div><button class="btn btn-light" @click="showEnrollment=false;showEditEnrollment=false"><i class="bi bi-x-lg"></i></button></div><template v-if="showEditEnrollment"><label>Academic year *</label><select v-model="enrollmentEditForm.academic_year_id" class="form-select mb-3"><option v-for="y in years" :key="y.id" :value="y.id">{{y.name}}</option></select><label>Class *</label><select v-model="enrollmentEditForm.class_level_id" class="form-select mb-3"><option v-for="c in classRows" :key="c.id" :value="c.id">{{c.name}}</option></select><label>Stream</label><select v-model="enrollmentEditForm.stream_id" class="form-select mb-3"><option value="">No stream</option><option v-for="s in editAvailableStreams" :key="s.id" :value="s.id">{{s.name}}</option></select><div class="row g-3 mb-3"><div class="col-6"><label>Enrollment date *</label><input v-model="enrollmentEditForm.enrollment_date" type="date" class="form-control"></div><div class="col-6"><label>Status</label><select v-model="enrollmentEditForm.status" class="form-select"><option value="active">Active</option><option value="completed">Completed</option><option value="withdrawn">Withdrawn</option></select></div></div><label>Exit date</label><input v-model="enrollmentEditForm.exit_date" type="date" class="form-control mb-3"><label>Notes</label><textarea v-model="enrollmentEditForm.notes" class="form-control mb-4" rows="2"></textarea></template><template v-else><label>Academic year *</label><select v-model="enrollmentForm.academic_year_id" class="form-select mb-3"><option value="">Select year</option><option v-for="y in years" :key="y.id" :value="y.id">{{y.name}}</option></select><label>Class *</label><select v-model="enrollmentForm.class_level_id" class="form-select mb-3"><option value="">Select class</option><option v-for="c in classRows" :key="c.id" :value="c.id">{{c.name}}</option></select><label>Stream</label><select v-model="enrollmentForm.stream_id" class="form-select mb-3"><option value="">No stream</option><option v-for="s in availableStreams" :key="s.id" :value="s.id">{{s.name}}</option></select><div class="row g-3 mb-3"><div class="col-6"><label>Enrollment date *</label><input v-model="enrollmentForm.enrollment_date" type="date" class="form-control"></div><div class="col-6"><label>Status</label><select v-model="enrollmentForm.status" class="form-select"><option value="active">Active</option><option value="completed">Completed</option><option value="withdrawn">Withdrawn</option></select></div></div><label>Notes</label><textarea v-model="enrollmentForm.notes" class="form-control mb-4" rows="2"></textarea></template><div class="modal-actions"><button class="btn btn-light" @click="showEnrollment=false;showEditEnrollment=false">Cancel</button><button v-if="showEditEnrollment" class="btn btn-primary" :disabled="saving||!enrollmentEditForm.academic_year_id||!enrollmentEditForm.class_level_id" @click="saveEnrollmentEdit">{{saving?'Updating...':'Update enrollment'}}</button><button v-else class="btn btn-primary" :disabled="saving||!enrollmentForm.academic_year_id||!enrollmentForm.class_level_id" @click="enroll">Save enrollment</button></div></div></div>
</div></template>
